function model(){return '<svg class="model" viewBox="0 0 1200 380" role="img" aria-label="Расписание комнаты на день управляет бронями. Бронь содержит временной интервал."><defs><marker id="modelArrow" markerWidth="9" markerHeight="9" refX="8" refY="4.5" orient="auto"><path d="M0 0L9 4.5L0 9" fill="#98baff"/></marker></defs><g class="node '+(modelStep<1?'mutedNode':'')+'"><rect x="270" y="15" width="900" height="345" rx="20" fill="#151d28" stroke="#71839c" stroke-dasharray="9 7"/><rect class="box root" x="465" y="45" width="440" height="115" rx="16"/><text class="title" x="490" y="80">RoomSchedule</text><text class="small" x="490" y="115">Комната + день · версия</text><text class="small" x="490" y="146">Book / Cancel / Reschedule</text></g><g class="node '+(modelStep<2?'mutedNode':'')+'"><path class="link" d="M610 160V190H485V215" marker-end="url(#modelArrow)"/><text class="small" x="310" y="187">проверяет и изменяет</text><rect class="box" x="310" y="220" width="380" height="120" rx="16"/><text class="title" x="335" y="255">Booking · бронь</text><text class="small" x="335" y="287">ID · организатор · статус</text><text class="small" x="335" y="320">Проверяет автора и статус</text></g><g class="node '+(modelStep<3?'mutedNode':'')+'"><rect class="box" x="15" y="50" width="230" height="120" rx="16"/><text class="title" x="35" y="85">Room</text><text class="small" x="35" y="119">ID · название</text><text class="small" x="35" y="150">Вместимость</text><path class="link" d="M465 105H245" marker-end="url(#modelArrow)"/><text class="small" x="285" y="90">для комнаты</text></g><g class="node '+(modelStep<4?'mutedNode':'')+'"><path class="link" d="M690 280H765" marker-end="url(#modelArrow)"/><text class="small" x="704" y="264">имеет</text><rect class="box vo" x="775" y="220" width="350" height="120" rx="16"/><text class="title" x="795" y="255">TimeInterval</text><text class="small" x="795" y="287">Начало &lt; конец</text><text class="small" x="795" y="320">Проверяет пересечение</text></g></svg>'}
function dependenciesHtml(){return head('Зависимости кода')+`<div class="sheet"><svg class="depDiagram" viewBox="0 0 1200 490" role="img" aria-label="UI зависит от Application. Application зависит от Domain. Infrastructure реализует интерфейс Domain. Domain не знает о базе и экране."><defs><marker id="depArrow" markerWidth="9" markerHeight="9" refX="8" refY="4.5" orient="auto"><path d="M0 0L9 4.5L0 9" style="fill:#3159cf;stroke:none"/></marker></defs><rect class="box" x="25" y="60" width="240" height="130" rx="18"/><text class="title" x="50" y="102">UI</text><text x="50" y="143">Экран / бот</text><path d="M265 122H405" marker-end="url(#depArrow)"/><text x="275" y="101">вызывает</text><rect class="box" x="425" y="60" width="310" height="130" rx="18"/><text class="title" x="450" y="102">Application</text><text x="450" y="143">Создать бронь</text><path d="M735 122H835" marker-end="url(#depArrow)"/><text x="750" y="101">типы</text><rect class="box core" x="855" y="60" width="320" height="240" rx="18"/><text class="title" x="880" y="102">Domain</text><text x="880" y="147">Расписание и бронь</text><text x="880" y="187">Правила</text><text x="880" y="227">Интерфейс хранилища</text><text x="880" y="267">Без EF Core и Telegram</text><rect class="box" x="425" y="350" width="310" height="120" rx="18"/><text class="title" x="450" y="393">Infrastructure</text><text x="450" y="434">Конкретная база</text><path class="dotted" d="M735 410H1010V315" marker-end="url(#depArrow)"/><text x="770" y="391">реализует интерфейс</text><text x="30" y="295">Стрелка → использует код</text></svg></div>`+prompt('Как сменить базу, не переписывая Booking и TimeInterval?')}